    bank_set = set(bank)
    choices = "ACGT"
    queue = deque([startGene])
    visited = {startGene}
    mutations = 0
    while queue:
        for _ in range(len(queue)):
            gene = queue.popleft()
            if gene == endGene:
                return mutations
            for p in range(len(gene)):
                for ch in choices:
                    if ch == gene[p]:
                        continue
                    mutated = gene[:p] + ch + gene[p + 1:]
                    if mutated in bank_set and mutated not in visited:
                        visited.add(mutated)
                        queue.append(mutated)
        mutations += 1
    return -1

