from collections import deque

def minMutation(self, startGene: str, endGene: str, bank: list[str]) -> int:
    def one_away(a: str, b: str) -> bool:
        diff = 0
        for x, y in zip(a, b):
            if x != y:
                diff += 1
                if diff > 1:
                    return False
        return diff == 1

    queue = deque([startGene])
    visited = {startGene}
    mutations = 0
    while queue:
        for _ in range(len(queue)):
            gene = queue.popleft()
            if gene == endGene:
                return mutations
            for candidate in bank:
                if candidate not in visited and one_away(gene, candidate):
                    visited.add(candidate)
                    queue.append(candidate)
        mutations += 1
    return -1

